"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raise the CPU limit of the 'api' container to 750m, which is 1.5 times its current limit of 500m, to clear the throttling observed in ev-container_cpu.",
  "rationale": "The new version (revision 2) uses more CPU than the previous version (revision 1), as evidenced by higher CPU usage (88% vs 45%) and increased throttling (61% vs 12%) in ev-revision_health and ev-rollout_history. The readiness probe failures (ev-target_events) align with CPU throttling causing delays. Raising the CPU limit to 750m should alleviate the throttling without affecting memory or other resources.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history", "ev-revision_health", "ev-target_events"],
  "cited_predicates": ["throttling_came_with_rollout", "cpu_usage_near_limit", "cpu_throttled_at_limit", "rollout_changed_the_app"]
}
